/**
 * Physics Info - Performance Metrics and Analytics
 *
 * Provides real-time physics performance metrics and body analytics,
 * similar to Three.js's renderer.info pattern.
 *
 * All metrics are lazily evaluated via getters, reading directly from
 * SharedArrayBuffer views for minimal overhead.
 *
 * @example
 * ```js
 * const physics = new Physics();
 * await physics.init();
 *
 * // Access timing metrics
 * console.log(physics.info.timing.fps);       // Physics FPS
 * console.log(physics.info.timing.stepTime);  // Step execution time (ms)
 *
 * // Access body counts
 * console.log(physics.info.bodies.total);     // Total body slots
 * console.log(physics.info.bodies.active);    // Total active bodies
 * console.log(physics.info.bodies.dynamic);   // { active: 1, total: 16 }
 *
 * // Access body state aggregates
 * console.log(physics.info.state.grounded);   // Bodies touching ground
 * console.log(physics.info.state.sleeping);   // Bodies in sleep state
 * ```
 *
 * @class PhysicsInfo
 * @short Real-time physics performance metrics and body analytics
 * @category Core
 * @tags Physics, Debug, WebGPU, WebGL
 * @public
 */
/**
 * Physics performance and analytics info object.
 * Provides lazy-evaluated metrics from SharedArrayBuffer views.
 */
export class PhysicsInfo {
    /**
     * Create a new PhysicsInfo instance.
     * @param {Physics} physicsAPI - The Physics instance to read metrics from
     */
    constructor(physicsAPI: Physics);
    _api: Physics;
    /**
     * Get the active physics model.
     * @returns {Object|null} The active physics model or null
     */
    get physicsModel(): any | null;
    /**
     * Body counts - total summary and per-type breakdown.
     * @returns {Object} Body count metrics
     */
    get bodies(): any;
    /**
     * Performance timing metrics.
     * @returns {Object} Timing metrics
     */
    get timing(): any;
    /**
     * Body state aggregates (for dynamic bodies).
     * @returns {Object} State counts
     */
    get state(): any;
    /**
     * Collision tracking metrics.
     * @returns {Object} Collision metrics
     */
    get collisions(): any;
    /**
     * Memory usage metrics.
     * @returns {Object} Memory metrics
     */
    get memory(): any;
    /**
     * Reset any frame-specific counters.
     * Currently a placeholder for future use.
     */
    reset(): void;
    /**
     * Count active bodies in a BBO array view.
     * @private
     * @param {Array} view - BBO array view
     * @param {number} max - Maximum body count
     * @returns {number} Active body count
     */
    private _countActive;
    /**
     * Count active in-reach triggers.
     * @private
     * @param {Float32Array} view - In-reach view (4 floats per item: used, x, y, z)
     * @param {number} max - Maximum in-reach count
     * @returns {number} Active in-reach count
     */
    private _countActiveInReach;
}
export default PhysicsInfo;
